from typing import Optional, Any, List, Dict, Union
from pydantic_settings import BaseSettings
from functools import lru_cache
import os
from pydantic import ValidationError


class TypeValidator:
    """Type validator for string, integer, boolean, array, object types."""

    @staticmethod
    def validate_string(value: Any, default: str = "") -> str:
        """Validate and convert value to string."""
        if value is None:
            return default
        if isinstance(value, str):
            return value
        return str(value)

    @staticmethod
    def validate_integer(value: Any, default: int = 0) -> int:
        """Validate and convert value to integer."""
        if value is None:
            return default
        if isinstance(value, int) and not isinstance(value, bool):
            return value
        if isinstance(value, str):
            try:
                return int(value)
            except ValueError:
                return default
        try:
            return int(value)
        except (ValueError, TypeError):
            return default

    @staticmethod
    def validate_boolean(value: Any, default: bool = False) -> bool:
        """Validate and convert value to boolean."""
        if value is None:
            return default
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            lower_value = value.lower().strip()
            if lower_value in ("true", "1", "yes", "on"):
                return True
            if lower_value in ("false", "0", "no", "off"):
                return False
            return default
        return bool(value)

    @staticmethod
    def validate_array(value: Any, default: List = None) -> List:
        """Validate and convert value to array/list."""
        if default is None:
            default = []
        if value is None:
            return default
        if isinstance(value, list):
            return value
        if isinstance(value, (tuple, set)):
            return list(value)
        if isinstance(value, str):
            if not value:
                return default
            return [item.strip() for item in value.split(",")]
        return default

    @staticmethod
    def validate_object(value: Any, default: Dict = None) -> Dict:
        """Validate and convert value to object/dict."""
        if default is None:
            default = {}
        if value is None:
            return default
        if isinstance(value, dict):
            return value
        if isinstance(value, str):
            if not value:
                return default
            try:
                import json
                return json.loads(value)
            except (ValueError, json.JSONDecodeError):
                return default
        return default

    @staticmethod
    def validate_type(value: Any, expected_type: str, default: Any = None) -> Any:
        """Validate value based on expected type string."""
        type_mapping = {
            "str": TypeValidator.validate_string,
            "string": TypeValidator.validate_string,
            "int": TypeValidator.validate_integer,
            "integer": TypeValidator.validate_integer,
            "bool": TypeValidator.validate_boolean,
            "boolean": TypeValidator.validate_boolean,
            "list": TypeValidator.validate_array,
            "array": TypeValidator.validate_array,
            "dict": TypeValidator.validate_object,
            "object": TypeValidator.validate_object,
        }

        validator_func = type_mapping.get(expected_type.lower())
        if validator_func:
            return validator_func(value, default)
        return default


