class EnumValidator:
    """枚举验证器，用于验证配置项的值是否在预定义的可选值列表中"""

    @staticmethod
    def validate(value: Any, allowed_values: list, field_name: str) -> Any:
        """
        验证值是否在允许的枚举值列表中

        Args:
            value: 待验证的值
            allowed_values: 允许的值列表
            field_name: 字段名称（用于错误信息）

        Returns:
            验证通过返回原值

        Raises:
            ValueError: 当值不在允许的列表中时
        """
        if value not in allowed_values:
            raise ValueError(
                f"{field_name} must be one of {allowed_values}, got: {value}"
            )
        return value

    @classmethod
    def create_validator(cls, allowed_values: list, field_name: str):
        """
        创建用于 Pydantic field_validator 的验证方法

        Args:
            allowed_values: 允许的值列表
            field_name: 字段名称（用于错误信息）

        Returns:
            验证方法
        """
        def validator(cls, v):
            return cls.validate(v, allowed_values, field_name)
        return validator


