from typing import Optional, Any, List, Dict, Union, Callable
from pydantic_settings import BaseSettings
from functools import lru_cache
import os
from pydantic import ValidationError, field_validator, model_validator


class TypeValidator:
    """Type validator for string, integer, boolean, array, object types."""

    @staticmethod
    def validate_string(value: Any, default: str = "") -> str:
        """Validate and convert value to string."""
        if value is None:
            return default
        if isinstance(value, str):
            return value
        return str(value)

    @staticmethod
    def validate_integer(value: Any, default: int = 0) -> int:
        """Validate and convert value to integer."""
        if value is None:
            return default
        if isinstance(value, int) and not isinstance(value, bool):
            return value
        if isinstance(value, str):
            try:
                return int(value)
            except ValueError:
                return default
        try:
            return int(value)
        except (ValueError, TypeError):
            return default

    @staticmethod
    def validate_boolean(value: Any, default: bool = False) -> bool:
        """Validate and convert value to boolean."""
        if value is None:
            return default
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            lower_value = value.lower().strip()
            if lower_value in ("true", "1", "yes", "on"):
                return True
            if lower_value in ("false", "0", "no", "off"):
                return False
            return default
        return bool(value)

    @staticmethod
    def validate_array(value: Any, default: List = None) -> List:
        """Validate and convert value to array/list."""
        if default is None:
            default = []
        if value is None:
            return default
        if isinstance(value, list):
            return value
        if isinstance(value, (tuple, set)):
            return list(value)
        if isinstance(value, str):
            if not value:
                return default
            return [item.strip() for item in value.split(",")]
        return default

    @staticmethod
    def validate_object(value: Any, default: Dict = None) -> Dict:
        """Validate and convert value to object/dict."""
        if default is None:
            default = {}
        if value is None:
            return default
        if isinstance(value, dict):
            return value
        if isinstance(value, str):
            if not value:
                return default
            try:
                import json
                return json.loads(value)
            except json.JSONDecodeError:
                return default
        return default


class DependencyRule:
    """Represents a single dependency rule between configuration fields."""

    def __init__(
        self,
        source_field: str,
        required_fields: List[str],
        condition: Optional[Callable[[Any], bool]] = None,
        error_message: Optional[str] = None
    ):
        """
        Initialize a dependency rule.

        Args:
            source_field: The field that triggers the dependency check
            required_fields: List of fields that must be present when source_field is set
            condition: Optional callable to determine if the rule should be applied
            error_message: Custom error message for validation failure
        """
        self.source_field = source_field
        self.required_fields = required_fields
        self.condition = condition
        self.error_message = error_message or (
            f"Configuration '{source_field}' is set, but the following fields are required: "
            f"{', '.join(required_fields)}"
        )

    def is_applicable(self, value: Any) -> bool:
        """Check if this rule is applicable based on the source field value."""
        if self.condition is not None:
            return self.condition(value)
        # Default: rule applies if source field is not None/empty
        if value is None:
            return False
        if isinstance(value, (str, list, dict)) and not value:
            return False
        return True

    def validate(self, config: Dict[str, Any]) -> Optional[str]:
        """Validate the dependency rule against the configuration."""
        source_value = config.get(self.source_field)

        if not self.is_applicable(source_value):
            return None

        missing_fields = []
        for field in self.required_fields:
            if field not in config or config[field] is None:
                missing_fields.append(field)

        if missing_fields:
            return self.error_message.format(
                source=self.source_field,
                required=', '.join(missing_fields)
            )
        return None


class DependencyValidator:
    """Validator for configuration dependencies."""

    def __init__(self):
        self.rules: List[DependencyRule] = []

    def add_rule(self, rule: DependencyRule) -> 'DependencyValidator':
        """Add a dependency rule."""
        self.rules.append(rule)
        return self

    def add_requirement(
        self,
        source_field: str,
        required_fields: List[str],
        condition: Optional[Callable[[Any], bool]] = None,
        error_message: Optional[str] = None
    ) -> 'DependencyValidator':
        """Add a requirement rule: when source_field is set, required_fields must also be set."""
        rule = DependencyRule(
            source_field=source_field,
            required_fields=required_fields,
            condition=condition,
