    ) -> 'DependencyValidator':
        """Add a mutual requirement: either both fields are set or neither."""
        msg = error_message or f"Fields '{field_a}' and '{field_b}' must be both present or both absent"

        # Rule: if field_a is set, field_b must be set
        self.add_requirement(
            source_field=field_a,
            required_fields=[field_b],
            error_message=msg
        )
        # Rule: if field_b is set, field_a must be set
        self.add_requirement(
            source_field=field_b,
            required_fields=[field_a],
            error_message=msg
        )
        return self

