            config: Dictionary of configuration values

        Returns:
            List of error messages (empty if all validations pass)
        """
        errors = []
        for rule in self.rules:
            error = rule.validate(config)
            if error:
                errors.append(error)
        return errors

    def validate_or_raise(self, config: Dict[str, Any]) -> None:
        """Validate and raise ValidationError if any rules are violated."""
