            field_metadata = self._validation_metadata.get(field_name, {})

            # 检查必需字段
            if field_metadata.get("required", False) and (value is None or value == ""):
                errors.append(f"{field_name} is required but not set")

            # 执行自定义验证器
            validator_name = field_metadata.get("validators", [])
            if isinstance(validator_name, str):
                validator_name = [validator_name]

            for validator in validator_name:
