class JSONConfigSourceValidator:
    """JSON configuration source validator."""

    def __init__(self, file_path: str):
        self.file_path = file_path
        self.errors: List[str] = []
        self.warnings: List[str] = []

    def validate(self) -> bool:
        """Validate JSON configuration file."""
        self.errors.clear()
        self.warnings.clear()

        # Check file exists
        if not self._check_file_exists():
            return False

        # Check file is valid JSON
        if not self._check_valid_json():
            return False

        # Check file permissions
        self._check_file_permissions()

        # Check for required fields
        self._check_required_fields()

        # Validate value types
        self._validate_value_types()

        # Check for circular references
        self._check_circular_references()

        return len(self.errors) == 0

    def _check_file_exists(self) -> bool:
        """Check if JSON file exists."""
        path = Path(self.file_path)
        if not path.exists():
            self.errors.append(f"JSON config file not found: {self.file_path}")
            return False
        if not path.is_file():
            self.errors.append(f"Path is not a file: {self.file_path}")
            return False
        return True

    def _check_valid_json(self) -> bool:
        """Check if JSON file is valid."""
        try:
            with open(self.file_path, 'r', encoding='utf-8') as f:
                json.load(f)
            return True
        except json.JSONDecodeError as e:
            self.errors.append(f"Invalid JSON format: {str(e)}")
            return False
        except Exception as e:
            self.errors.append(f"Error reading JSON file: {str(e)}")
            return False

    def _check_file_permissions(self):
        """Check file read permissions."""
        path = Path(self.file_path)
        if not os.access(path, os.R_OK):
            self.errors.append(f"File is not readable: {self.file_path}")

    def _check_required_fields(self):
        """Check for common required configuration fields."""
        try:
            with open(self.file_path, 'r', encoding='utf-8') as f:
                config = json.load(f)

            # Check for empty config
            if not config:
                self.warnings.append("JSON configuration file is empty")
                return

            # Check for common required fields
            required_fields = ['app_name', 'version']
            for field in required_fields:
                if field not in config:
                    self.warnings.append(f"Recommended field '{field}' not found in configuration")

        except Exception:
            pass

    def _validate_value_types(self):
        """Validate configuration value types."""
        try:
            with open(self.file_path, 'r', encoding='utf-8') as f:
                config = json.load(f)

            for key, value in config.items():
                if value is None:
                    self.warnings.append(f"Configuration key '{key}' has null value")
                elif isinstance(value, dict):
                    self._validate_nested_dict(key, value)

        except Exception:
            pass

    def _validate_nested_dict(self, parent_key: str, data: Dict):
        """Validate nested dictionary configurations."""
        for key, value in data.items():
            full_key = f"{parent_key}.{key}"
            if value is None:
                self.warnings.append(f"Configuration key '{full_key}' has null value")
            elif isinstance(value, dict):
                self._validate_nested_dict(full_key, value)

    def _check_circular_references(self):
        """Check for potential circular reference patterns."""
        try:
            with open(self.file_path, 'r', encoding='utf-8') as f:
                content = f.read()

            # Check for common circular reference patterns
            patterns = [
                r'\$\{.*\$\{',
                r'\$\{self\.',
                r'\$\{parent\.',
            ]

            for pattern in patterns:
                if re.search(pattern, content):
                    self.warnings.append("Potential circular reference detected")
                    break

        except Exception:
            pass

    def get_errors(self) -> List[str]:
        """Get validation errors."""
        return self.errors

    def get_warnings(self) -> List[str]:
        """Get validation warnings."""
        return self.warnings

    def get_config(self) -> Optional[Dict]:
        """Load and return configuration dictionary."""
        try:
            with open(self.file_path, 'r', encoding='utf-8') as f:
                return json.load(f)
        except Exception:
            return None


class ConfigValidatorFactory:
    """Configuration validator factory singleton."""

    _instance = None
    _validators = {}

    def __new__(cls):
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._initialized = False
        return cls._instance

    def __init__(self):
        if self._initialized:
            return
        self._initialized = True
        self._register_builtin_validators()

    def _register_builtin_validators(self):
        """Register all built-in validators."""
        # Type validators
        self.register_validator("type_string", self._validate_type_string)
        self.register_validator("type_int", self._validate_type_int)
        self.register_validator("type_float", self._validate_type_float)
        self.register_validator("type_bool", self._validate_type_bool)

        # Range validators
        self.register_validator("range", self._validate_range)

        # Enum validators
        self.register_validator("enum", self._validate_enum)

        # Regex validators
        self.register_validator("regex", self._validate_regex)

        # Dependencies validators
        self.register_validator("dependencies", self._validate_dependencies)

        # JSON config source validators
        self.register_validator("json_source", self._validate_json_source)

    def register_validator(self, name: str, validator: Callable):
        """Register a custom validator."""
        self._validators[name] = validator

    def get_validator(self, name: str) -> Optional[Callable]:
        """Get a validator by name."""
        return self._validators.get(name)

    def validate_config(self, metadata: ConfigMetadata, value: Any) -> tuple[bool, Optional[str]]:
        """Validate a configuration value against its metadata."""
        # Type validation
        type_validators = {
            str: "type_string",
            int: "type_int",
            float: "type_float",
            bool: "type_bool",
        }

        if metadata.type in type_validators:
            validator_name = type_validators[metadata.type]
            validator = self.get_validator(validator_name)
            if validator:
                is_valid, error = validator(value)
                if not is_valid:
                    return False, error

        # Range validation
        if metadata.min is not None or metadata.max is not None:
            validator = self.get_validator("range")
            if validator:
                is_valid, error = validator(value, metadata.min, metadata.max)
                if not is_valid:
                    return False, error

        # Enum validation
        if metadata.enum_values is not None:
            validator = self.get_validator("enum")
            if validator:
                is_valid, error = validator(value, metadata.enum_values)
                if not is_valid:
                    return False, error

        # Regex validation
        if metadata.regex_pattern is not None:
            validator = self.get_validator("regex")
            if validator:
                is_valid, error = validator(value, metadata.regex_pattern)
                if not is_valid:
                    return False, error

        # Custom validator
        if metadata.validator_func is not None:
            try:
                metadata.validator_func(value)
            except Exception as e:
                return False, str(e)

        return True, None

    def _validate_type_string(self, value: Any) -> tuple[bool, Optional[str]]:
        """Validate string type."""
        if not isinstance(value, str):
            return False, f"Expected string, got {type(value).__name__}"
        return True, None

    def _validate_type_int(self, value: Any) -> tuple[bool, Optional[str]]:
        """Validate integer type."""
        if not isinstance(value, int) or isinstance(value, bool):
            return False, f"Expected integer, got {type(value).__name__}"
        return True, None

    def _validate_type_float(self, value: Any) -> tuple[bool, Optional[str]]:
        """Validate float type."""
        if not isinstance(value, (int, float)) or isinstance(value, bool):
            return False, f"Expected float, got {type(value).__name__}"
        return True, None

    def _validate_type_bool(self, value: Any) -> tuple[bool, Optional[str]]:
        """Validate boolean type."""
        if not isinstance(value, bool):
            return False, f"Expected boolean, got {type(value).__name__}"
        return True, None

    def _validate_range(self, value: Any, min_val: Optional[Any] = None, max_val: Optional[Any] = None) -> tuple[bool, Optional[str]]:
        """Validate value is within range."""
        if min_val is not None and value < min_val:
            return False, f"Value {value} is less than minimum {min_val}"
        if max_val is not None and value > max_val:
            return False, f"Value {value} is greater than maximum {max_val}"
        return True, None

    def _validate_enum(self, value: Any, enum_values: List[Any]) -> tuple[bool, Optional[str]]:
        """Validate value is in enum list."""
        if value not in enum_values:
            return False, f"Value {value} not in allowed values: {enum_values}"
        return True, None

    def _validate_regex(self, value: Any, pattern: str) -> tuple[bool, Optional[str]]:
        """Validate value matches regex pattern."""
        if not isinstance(value, str):
            return False, "Value must be string for regex validation"
        if not re.match(pattern, value):
            return False, f"Value does not match pattern: {pattern}"
        return True, None

    def _validate_dependencies(self, value: Any, config: Dict[str, Any], dependencies: List[str]) -> tuple[bool, Optional[str]]:
        """Validate configuration dependencies."""
        for dep in dependencies:
            if dep not in config:
                return False, f"Missing required dependency: {dep}"
        return True, None

    def _validate_json_source(self, file_path: str) -> tuple[bool, Optional[str]]:
        """Validate JSON configuration source file."""
        validator = JSONConfigSourceValidator(file_path)
        if validator.validate():
            return True, None
        errors = validator.get_errors()
        return False, "; ".join(errors) if errors else "Unknown validation error"


@lru_cache()
def get_config_validator_factory() -> ConfigValidatorFactory:
    """Get the configuration validator factory instance."""
    return ConfigValidatorFactory()

"""
Application configuration settings.
"""
from typing import Optional, Any, Dict, List, Callable
from pydantic_settings import BaseSettings
from functools import lru_cache
import os
from pydantic import ValidationError, field_validator, Field
from enum import Enum
from dataclasses import dataclass, field


class FailureStrategy(Enum):
    """失败策略枚举"""
    TERMINATE = "terminate"      # 终止程序
    USE_DEFAULT = "use_default"  # 使用默认值
    ROLLBACK = "rollback"        # 回滚配置


@dataclass
class ValidationResult:
    """验证结果"""
    source: str
    is_valid: bool
    errors: List[str] = field(default_factory=list)
    warnings: List[str] = field(default_factory=list)


@dataclass
class ValidationReport:
    """验证报告"""
    total_sources: int = 0
    valid_sources: int = 0
    invalid_sources: int = 0
    results: List[ValidationResult] = field(default_factory=list)


class EnvConfigSource:
    """环境变量配置源验证器"""

    def __init__(self, prefix: str = "APP_", required_vars: Optional[List[str]] = None,
                 var_types: Optional[Dict[str, type]] = None,
                 var_constraints: Optional[Dict[str, Callable]] = None):
        """
        初始化环境变量配置源验证器

        Args:
            prefix: 环境变量前缀过滤
            required_vars: 必需的环境变量列表
            var_types: 环境变量类型映射 {"VAR_NAME": type}
            var_constraints: 环境变量约束函数 {"VAR_NAME": callable}
        """
        self.prefix = prefix
        self.required_vars = required_vars or []
        self.var_types = var_types or {}
        self.var_constraints = var_constraints or {}
        self._env_cache: Dict[str, str] = {}

    def load_env_vars(self) -> Dict[str, str]:
        """加载所有以指定前缀开头的环境变量"""
        self._env_cache = {
            key: value for key, value in os.environ.items()
            if key.startswith(self.prefix)
        }
        return self._env_cache

    def get_env_var(self, name: str, default: Optional[str] = None) -> Optional[str]:
        """
        获取环境变量值

        Args:
            name: 环境变量名称（不含前缀）
            default: 默认值

        Returns:
            环境变量值或默认值
        """
        full_name = f"{self.prefix}{name}"
        return os.environ.get(full_name, default)

    def set_env_var(self, name: str, value: str) -> None:
        """
        设置环境变量（仅影响缓存，不影响实际进程环境）

        Args:
            name: 环境变量名称（不含前缀）
            value: 环境变量值
        """
        full_name = f"{self.prefix}{name}"
        self._env_cache[full_name] = value

    def validate(self) -> ValidationResult:
        """
        验证环境变量配置

        Returns:
            ValidationResult: 验证结果
        """
        errors: List[str] = []
        warnings: List[str] = []

        # 加载环境变量
        self.load_env_vars()

        # 检查必需的环境变量
        for var_name in self.required_vars:
            full_name = f"{self.prefix}{var_name}"
            if full_name not in self._env_cache:
                errors.append(f"Required environment variable missing: {full_name}")

        # 验证类型
        for var_name, expected_type in self.var_types.items():
            full_name = f"{self.prefix}{var_name}"
            if full_name in self._env_cache:
                value = self._env_cache[full_name]
                try:
                    if expected_type == bool:
                        if value.lower() not in ('true', 'false', '1', '0', 'yes', 'no'):
                            errors.append(
                                f"Invalid boolean value for {full_name}: {value}"
                            )
                    elif expected_type == int:
                        int(value)
                    elif expected_type == float:
                        float(value)
                except (ValueError, TypeError) as e:
                    errors.append(
                        f"Invalid type for {full_name}: expected {expected_type.__name__}, got '{value}'"
                    )

        # 验证约束
        for var_name, constraint_func in self.var_constraints.items():
            full_name = f"{self.prefix}{var_name}"
            if full_name in self._env_cache:
                value = self._env_cache[full_name]
                try:
                    if not constraint_func(value):
                        warnings.append(
                            f"Value for {full_name} did not pass constraint check: {value}"
                        )
                except Exception as e:
                    errors.append(
                        f"Constraint validation failed for {full_name}: {str(e)}"
                    )

        is_valid = len(errors) == 0

        return ValidationResult(
            source=f"env_config_source({self.prefix})",
            is_valid=is_valid,
            errors=errors,
            warnings=warnings
        )

    def validate_value(self, name: str, value: Any) -> bool:
        """
        验证单个环境变量值

        Args:
            name: 环境变量名称（不含前缀）
            value: 要验证的值

        Returns:
            bool: 验证是否通过
        """
        full_name = f"{self.prefix}{name}"

        # 类型检查
        if name in self.var_types:
            expected_type = self.var_types[name]
            try:
                if expected_type == bool:
                    if isinstance(value, bool):
                        return True
                    if isinstance(value, str) and value.lower() in ('true', 'false', '1', '0', 'yes', 'no'):
                        return True
                    return False
                elif expected_type in (int, float, str):
                    expected_type(value)
                    return True
                else:
                    expected_type(value)
                    return True
            except (ValueError, TypeError):
                return False

        # 约束检查
        if name in self.var_constraints:
            try:
                return self.var_constraints[name](value)
            except Exception:
                return False

        return True


class ConfigValidationRunner:
    """配置验证运行器"""

    def __init__(self):
        self._failure_strategy: FailureStrategy = FailureStrategy.TERMINATE
        self._validation_report: ValidationReport = ValidationReport()
        self._config_sources: Dict[str, Any] = {}

    def set_failure_strategy(self, strategy: str) -> None:
        """
        设置失败策略

        Args:
            strategy: 策略名称，可选值：terminate/use_default/rollback

        Raises:
            ValueError: 当策略名称无效时
        """
        try:
            self._failure_strategy = FailureStrategy(strategy)
        except ValueError:
            raise ValueError(
                f"Invalid failure strategy: {strategy}. "
                f"Must be one of {[s.value for s in FailureStrategy]}"
            )

    def get_failure_strategy(self) -> FailureStrategy:
        """获取当前失败策略"""
        return self._failure_strategy

    def register_config_source(self, name: str, config: Any) -> None:
        """
        注册配置源

        Args:
            name: 配置源名称
            config: 配置对象（通常是 Pydantic Settings 实例）
        """
        self._config_sources[name] = config

    def validate_source(self, source_name: str) -> ValidationResult:
        """
        验证单个配置源

        Args:
            source_name: 配置源名称

        Returns:
            ValidationResult: 验证结果
        """
        if source_name not in self._config_sources:
            return ValidationResult(
                source=source_name,
                is_valid=False,
                errors=[f"Config source not found: {source_name}"]
            )

        config = self._config_sources[source_name]

        # 如果是 EnvConfigSource，使用其验证方法
        if isinstance(config, EnvConfigSource):
            return config.validate()

        # 如果是 Pydantic Settings 实例
        if isinstance(config, BaseSettings):
            try:
                # 触发所有字段的验证
                config.model_dump()
                return ValidationResult(
                    source=source_name,
                    is_valid=True
                )
            except ValidationError as e:
                errors = [f"{err['loc']}: {err['msg']}" for err in e.errors()]
                return ValidationResult(
                    source=source_name,
                    is_valid=False,
                    errors=errors
                )

        # 通用验证
        return ValidationResult(
            source=source_name,
            is_valid=True
        )

    def run_validation(self) -> ValidationReport:
        """
        运行所有配置源的验证

        Returns:
            ValidationReport: 验证报告
        """
        report = ValidationReport()
        report.total_sources = len(self._config_sources)

        for name, config in self._config_sources.items():
            result = self.validate_source(name)
            report.results.append(result)

            if result.is_valid:
                report.valid_sources += 1
            else:
                report.invalid_sources += 1

        self._validation_report = report
        return report

    def handle_validation_failure(self, report: ValidationReport) -> None:
        """
        处理验证失败

        Args:
            report: 验证报告

        Raises:
            ValueError: 当策略为 TERMINATE 且验证失败时
        """
        if report.invalid_sources == 0:
            return

        if self._failure_strategy == FailureStrategy.TERMINATE:
            error_messages = []
            for result in report.results:
                if not result.is_valid:
                    error_messages.append(f"{result.source}: {', '.join(result.errors)}")
            raise ValueError(
                f"Configuration validation failed: {'; '.join(error_messages)}"
            )
        elif self._failure_strategy == FailureStrategy.USE_DEFAULT:
            # 使用默认配置的逻辑可以在这里实现
            pass
        elif self._failure_strategy == FailureStrategy.ROLLBACK:
            # 回滚配置的逻辑可以在这里实现
            pass

    def get_validation_report(self) -> ValidationReport:
        """获取验证报告"""
        return self._validation_report
